# owner: platform
import unittest

from hourglass.timesheet import timesheet_lines
from hourglass.parsing import parse_span
from hourglass.models import Shift


def make_shift(worker, day, text):
    return Shift(worker, day, parse_span(text))


class TimesheetLinesTests(unittest.TestCase):
    def test_busiest_first(self):
        lines = timesheet_lines([
            make_shift("Brisa", "mon", "09:00-10:00"),
            make_shift("Corin", "mon", "09:00-13:30"),
            make_shift("Brisa", "tue", "09:00-10:30")
        ])
        self.assertEqual(lines, [
            "Corin: 1 shift, 4.5 hours",
            "Brisa: 2 shifts, 2.5 hours"
        ])

    def test_ties_sorted_by_name(self):
        lines = timesheet_lines([
            make_shift("Zane", "mon", "09:00-10:00"),
            make_shift("Abel", "mon", "09:00-10:00")
        ])
        self.assertEqual(lines[0][:4], "Abel")

    def test_hours_rounded_to_one_decimal(self):
        lines = timesheet_lines([make_shift("Brisa", "mon", "09:00-09:20")])
        self.assertEqual(lines, ["Brisa: 1 shift, 0.3 hours"])

    def test_empty_list(self):
        with self.assertRaises(ValueError):
            timesheet_lines([])

    def test_blank_worker(self):
        with self.assertRaises(ValueError):
            timesheet_lines([make_shift("  ", "mon", "09:00-10:00")])
